create table if not exists users(id bigserial primary key,name varchar(120) not null,email varchar(255) unique not null,password_hash text not null,role varchar(30) not null default 'customer',created_at timestamptz default now());
create table if not exists service_categories(id bigserial primary key,name varchar(100) not null,slug varchar(100) unique not null,icon varchar(20));
create table if not exists professional_profiles(id bigserial primary key,user_id bigint unique references users(id) on delete cascade,category_id bigint references service_categories(id),city varchar(100),bio text,phone varchar(40),price_from numeric(12,2),rating numeric(3,2) default 0,review_count int default 0,approved boolean default false,created_at timestamptz default now());
create table if not exists service_requests(id bigserial primary key,customer_id bigint references users(id),professional_id bigint references professional_profiles(id),title varchar(180) not null,description text,city varchar(100),scheduled_at timestamptz,budget numeric(12,2),status varchar(30) default 'pending',created_at timestamptz default now());
create table if not exists reviews(id bigserial primary key,request_id bigint unique references service_requests(id),customer_id bigint references users(id),rating int check(rating between 1 and 5),comment text,created_at timestamptz default now());
